    /// <summary><c>metrics_observer</c> (internal).</summary>
    internal static readonly Statement MetricsObserver = new(
        "metrics_observer",
        "\n        WITH queue_names AS (\n          SELECT queue_name FROM workhorse.task_runtime\n          UNION\n          SELECT queue_name FROM workhorse.fast_task_runtime\n          UNION\n          SELECT queue_name FROM workhorse.queue_control\n        ), depth AS (\n          SELECT names.queue_name,\n         count(runtime.task_id) FILTER (WHERE runtime.state = 'scheduled')::text AS scheduled,\n         count(runtime.task_id) FILTER (WHERE runtime.state = 'ready')::text AS ready,\n         count(runtime.task_id) FILTER (WHERE runtime.state = 'active')::text AS active,\n         extract(epoch FROM clock_timestamp() - min(runtime.ready_at) FILTER (\n       WHERE runtime.state = 'ready'\n     )) * 1000 AS oldest_ready_age_ms,\n         count(runtime.task_id) FILTER (\n       WHERE runtime.state = 'active' AND runtime.expires_at <= clock_timestamp()\n     )::text AS expired,\n         count(runtime.task_id) FILTER (\n       WHERE runtime.deadline_at IS NOT NULL AND runtime.deadline_at <= clock_timestamp()\n     )::text AS overdue_deadlines,\n         count(runtime.task_id) FILTER (\n       WHERE runtime.state = 'active' AND runtime.attempt_timeout_at <= clock_timestamp()\n     )::text AS overdue_execution_timeouts\n      FROM queue_names names\n      LEFT JOIN (\n        SELECT task_id, queue_name, state, ready_at, expires_at, deadline_at, attempt_timeout_at\n          FROM workhorse.task_runtime\n        UNION ALL\n        SELECT task_id, queue_name,\n               CASE WHEN state = 'ready' AND run_at > clock_timestamp() THEN 'scheduled'\n                    ELSE state END,\n               CASE WHEN state = 'ready' THEN run_at END, expires_at, deadline_at,\n               attempt_timeout_at\n          FROM workhorse.fast_task_runtime\n      ) runtime\n        ON runtime.queue_name = names.queue_name\n     GROUP BY names.queue_name\n        )\n        SELECT depth.*, coalesce(control.paused, false) AS paused,\n               waits.pending_signal_waits, waits.pending_human_waits,\n               waits.overdue_signal_waits, waits.overdue_human_waits,\n               waits.rejected_signals, waits.rejected_human_waits\n          FROM depth\n          LEFT JOIN workhorse.queue_control control USING (queue_name)\n          CROSS JOIN LATERAL (\n            SELECT\n              (SELECT count(*)::text FROM (\n                SELECT 1 FROM workhorse.task_signal_wait signal\n                 JOIN workhorse.task_runtime runtime ON runtime.task_id = signal.task_id\n                WHERE runtime.queue_name = depth.queue_name\n                  AND runtime.state = 'scheduled' AND runtime.wait_name = signal.signal_name\n                  AND runtime.current_attempt = signal.attempt AND signal.delivered_at IS NULL\n                LIMIT 10001\n              ) sampled) AS pending_signal_waits,\n              (SELECT count(*)::text FROM (\n                SELECT 1 FROM workhorse.task_human_wait human_wait\n                 JOIN workhorse.task_runtime runtime ON runtime.task_id = human_wait.task_id\n                WHERE runtime.queue_name = depth.queue_name\n                  AND runtime.state = 'scheduled' AND runtime.wait_name = human_wait.token_name\n                  AND runtime.current_attempt = human_wait.attempt\n                  AND human_wait.completed_at IS NULL\n                LIMIT 10001\n              ) sampled) AS pending_human_waits,\n              (SELECT count(*)::text FROM (\n                SELECT 1 FROM workhorse.task_signal_wait signal\n                 JOIN workhorse.task_runtime runtime ON runtime.task_id = signal.task_id\n                WHERE runtime.queue_name = depth.queue_name\n                  AND runtime.state = 'scheduled' AND runtime.wait_name = signal.signal_name\n                  AND runtime.current_attempt = signal.attempt AND signal.delivered_at IS NULL\n                  AND runtime.deadline_at <= clock_timestamp()\n                LIMIT 10001\n              ) sampled) AS overdue_signal_waits,\n              (SELECT count(*)::text FROM (\n                SELECT 1 FROM workhorse.task_human_wait human_wait\n                 JOIN workhorse.task_runtime runtime ON runtime.task_id = human_wait.task_id\n                WHERE runtime.queue_name = depth.queue_name\n                  AND runtime.state = 'scheduled' AND runtime.wait_name = human_wait.token_name\n                  AND runtime.current_attempt = human_wait.attempt\n                  AND human_wait.completed_at IS NULL\n                  AND runtime.deadline_at <= clock_timestamp()\n                LIMIT 10001\n              ) sampled) AS overdue_human_waits,\n              (SELECT count(*)::text FROM (\n                SELECT 1 FROM workhorse.task_event event\n                 JOIN workhorse.task task ON task.id = event.task_id\n                WHERE task.queue_name = depth.queue_name AND event.event_type = 'signal_rejected'\n                  AND event.occurred_at >= $1::timestamptz\n                LIMIT 10001\n              ) sampled) AS rejected_signals,\n              (SELECT count(*)::text FROM (\n                SELECT 1 FROM workhorse.task_event event\n                 JOIN workhorse.task task ON task.id = event.task_id\n                WHERE task.queue_name = depth.queue_name\n                  AND event.event_type = 'human_wait_rejected'\n                  AND event.occurred_at >= $1::timestamptz\n                LIMIT 10001\n              ) sampled) AS rejected_human_waits\n          ) waits\n         ORDER BY depth.queue_name",
        1);

    /// <summary><c>maintenance_observer</c> (internal).</summary>
    internal static readonly Statement MaintenanceObserver = new(
        "maintenance_observer",
        "WITH health AS (\n          SELECT workhorse.queue_health_v1($1::timestamptz) AS document\n        ), installed AS (\n          SELECT min(installed_at) AS installed_at FROM workhorse.schema_version\n        ), policy AS (\n          SELECT timezone, partition_preparation_interval_ms, terminal_cleanup_interval_ms,\n                 history_retention_local_time, statistics_rollup_interval_ms, updated_at\n            FROM workhorse.maintenance_policy WHERE singleton LIMIT 1\n        ), tick AS (\n          -- The tick has no fleet cadence. Its shortest cadence among live workers is the due\n          -- interval, and with no live worker the tick is due again as soon as it completes. A\n          -- worker is live while its last heartbeat is within its own lease.\n          SELECT min(maintenance_interval_ms) AS interval_ms\n            FROM workhorse.worker_registry\n           WHERE last_heartbeat_at >= clock_timestamp() - make_interval(secs => lease_ms / 1000.0)\n        ), retention_start AS (\n          -- The daily pass is due on the first local date after its completed date, from the\n          -- first instant whose local time reaches the retention time. Only a policy change\n          -- clears the date, so a missing date makes the pass due from the latest of the\n          -- completion, the installation, and the last policy change. A start names a local\n          -- date, and an optional instant on it that the due time cannot precede.\n          SELECT start.local_date, start.not_before\n            FROM workhorse.maintenance_state state\n            CROSS JOIN installed\n            CROSS JOIN policy\n            CROSS JOIN workhorse.retention_policy retention\n            CROSS JOIN LATERAL (\n              SELECT GREATEST(\n                       COALESCE(state.last_completed_at, installed.installed_at),\n                       policy.updated_at, retention.updated_at\n                     ) AS at\n            ) cleared\n            CROSS JOIN LATERAL (\n              SELECT state.last_completed_local_date + 1 AS local_date,\n                     NULL::timestamptz AS not_before\n               WHERE state.last_completed_local_date IS NOT NULL\n              UNION ALL\n              SELECT (cleared.at AT TIME ZONE policy.timezone)::date, cleared.at\n               WHERE state.last_completed_local_date IS NULL\n            ) start\n           WHERE state.routine_name = 'history_retention' AND retention.singleton\n        ), retention_due AS (\n          -- A local time that a time zone change skips or repeats does not map to one instant,\n          -- so the search takes the first second of the local date that the scheduler accepts.\n          -- It finds the first accepted minute in the day before the target, then the first\n          -- accepted second in the minute before that.\n          SELECT eligible.at AS due_at\n            FROM retention_start start\n            CROSS JOIN policy\n            CROSS JOIN LATERAL (\n              SELECT (start.local_date + policy.history_retention_local_time)\n                       AT TIME ZONE policy.timezone AS target\n            ) clock\n            CROSS JOIN LATERAL (\n              SELECT start.not_before AS at\n               WHERE (start.not_before AT TIME ZONE policy.timezone)::time(0)\n                 >= policy.history_retention_local_time\n              UNION ALL\n              SELECT COALESCE((\n                       SELECT min(second)\n                         FROM generate_series(minute.at - interval '59 seconds', minute.at,\n                                              interval '1 second') second\n                        WHERE (second >= start.not_before OR start.not_before IS NULL)\n                          AND (second AT TIME ZONE policy.timezone)::date = start.local_date\n                          AND (second AT TIME ZONE policy.timezone)::time(0)\n                            >= policy.history_retention_local_time\n                     ), clock.target)\n                FROM (\n                  SELECT min(candidate) AS at\n                    FROM generate_series(\n                      clock.target - interval '26 hours', clock.target, interval '1 minute'\n                    ) candidate\n                   WHERE (candidate >= start.not_before OR start.not_before IS NULL)\n                     AND (candidate AT TIME ZONE policy.timezone)::date = start.local_date\n                     AND (candidate AT TIME ZONE policy.timezone)::time(0)\n                       >= policy.history_retention_local_time\n                ) minute\n               WHERE start.not_before IS NULL\n                  OR (start.not_before AT TIME ZONE policy.timezone)::time(0)\n                    < policy.history_retention_local_time\n            ) eligible\n        ), routine AS (\n          -- A routine that never completed is due at once, as each scheduler gate treats it.\n          SELECT state.routine_name,\n                 COALESCE(state.last_completed_at, installed.installed_at) AS completed_at,\n                 CASE\n                   WHEN state.routine_name = 'history_retention'\n                     THEN (SELECT due_at FROM retention_due)\n                   WHEN state.last_completed_at IS NULL THEN installed.installed_at\n                   WHEN state.routine_name = 'tick' THEN state.last_completed_at\n                     + make_interval(secs => COALESCE(tick.interval_ms, 0) / 1000.0)\n                   WHEN state.routine_name = 'history_partitions' THEN state.last_completed_at\n                     + make_interval(secs => policy.partition_preparation_interval_ms / 1000.0)\n                   -- A recorded backlog makes the follow-up pass due as\n                   -- prune_terminal_storage_v1 gates it.\n                   ELSE state.last_completed_at + make_interval(\n                     secs => CASE WHEN state.terminal_cleanup_backlog_since IS NULL\n                       THEN policy.terminal_cleanup_interval_ms\n                       ELSE LEAST(policy.terminal_cleanup_interval_ms,\n                         workhorse.terminal_cleanup_follow_up_delay_ms_v1()) END / 1000.0\n                   )\n                 END AS due_at\n            FROM workhorse.maintenance_state state\n            CROSS JOIN installed\n            CROSS JOIN policy\n            CROSS JOIN tick\n          UNION ALL\n          SELECT 'statistics_rollup', COALESCE(stat.last_run_at, installed.installed_at),\n                 CASE WHEN policy.statistics_rollup_interval_ms = 0 THEN NULL\n                      WHEN stat.last_run_at IS NULL THEN installed.installed_at\n                      ELSE stat.last_run_at + make_interval(\n                        secs => policy.statistics_rollup_interval_ms / 1000.0\n                      ) END\n            FROM workhorse.task_stat_state stat\n            CROSS JOIN installed\n            CROSS JOIN policy\n           WHERE stat.singleton\n        )\n        SELECT 'routine' AS kind, routine_name AS name,\n               GREATEST(0, extract(epoch FROM clock_timestamp() - completed_at) * 1000) AS age_ms,\n               COALESCE(GREATEST(0, extract(epoch FROM clock_timestamp() - due_at) * 1000), 0)\n                 AS overdue_ms,\n               NULL::numeric AS lag_ms, NULL::numeric AS budget_ms, NULL::boolean AS enabled\n          FROM routine\n        UNION ALL\n        SELECT 'retention', category.name, NULL, NULL,\n               COALESCE((health.document->>category.lag_key)::numeric, 0),\n               (health.document->'budgets'->>category.budget_key)::numeric,\n               category.retention_days IS NOT NULL\n          FROM health\n          CROSS JOIN workhorse.retention_policy retention\n          CROSS JOIN LATERAL (\n            VALUES\n              ('taskIdentity', 'task_identity_lag_ms', 'rowRetentionLagMs',\n                retention.task_identity_retention_days),\n              ('terminalOutcome', 'terminal_outcome_lag_ms', 'rowRetentionLagMs',\n                retention.terminal_outcome_retention_days),\n              ('taskEvents', 'task_event_lag_ms', 'partitionRetentionLagMs',\n                retention.task_event_retention_days),\n              ('attemptHistory', 'attempt_history_lag_ms', 'partitionRetentionLagMs',\n                retention.attempt_history_retention_days),\n              ('scheduleOccurrences', 'schedule_occurrence_lag_ms', 'rowRetentionLagMs',\n                retention.schedule_occurrence_retention_days),\n              ('statistics', 'statistics_lag_ms', 'rowRetentionLagMs',\n                retention.statistics_retention_days)\n          ) category(name, lag_key, budget_key, retention_days)\n         WHERE retention.singleton\n         ORDER BY kind, name",
        1);

    /// <summary><c>queue_metric_snapshot</c> (internal).</summary>
    internal static readonly Statement QueueMetricSnapshot = new(
        "queue_metric_snapshot",
        "WITH queue_names AS (\n         SELECT $1::text AS queue_name\n         UNION SELECT queue_name FROM workhorse.task_runtime\n         UNION SELECT queue_name FROM workhorse.fast_task_runtime\n         UNION SELECT queue_name FROM workhorse.queue_control\n         UNION SELECT queue_name FROM workhorse.concurrency_policy\n         UNION SELECT queue_name FROM workhorse.rate_limit_policy\n         UNION SELECT unnest(queue_names) FROM workhorse.worker_registry\n         UNION SELECT query.queue_name FROM workhorse.task_query query\n          JOIN workhorse.task_outcome outcome ON outcome.task_id = query.task_id\n         WHERE outcome.state = 'failed' AND outcome.error->>'name' = 'DependencyFailed'\n         UNION SELECT query.queue_name FROM workhorse.task_query query\n          JOIN workhorse.task_child edge ON edge.parent_task_id = query.task_id\n       ), usage AS (\n         SELECT names.queue_name,\n         count(runtime.task_id) FILTER (WHERE runtime.state = 'ready')::text AS ready,\n         count(runtime.task_id) FILTER (WHERE runtime.state = 'scheduled')::text AS scheduled,\n         count(runtime.task_id) FILTER (WHERE runtime.state = 'active')::text AS active,\n         count(runtime.task_id) FILTER (\n       WHERE runtime.state = 'active' AND runtime.expires_at > clock_timestamp()\n     )::text AS concurrency_active,\n         extract(epoch FROM clock_timestamp() - min(runtime.ready_at) FILTER (\n       WHERE runtime.state = 'ready'\n     )) * 1000 AS oldest_ready_age_ms\n      FROM queue_names names\n      LEFT JOIN (\n        SELECT task_id, queue_name, state, ready_at, expires_at\n          FROM workhorse.task_runtime\n        UNION ALL\n        SELECT task_id, queue_name,\n               CASE WHEN state = 'ready' AND run_at > clock_timestamp() THEN 'scheduled'\n                    ELSE state END,\n               CASE WHEN state = 'ready' THEN run_at END, expires_at\n          FROM workhorse.fast_task_runtime\n      ) runtime\n        ON runtime.queue_name = names.queue_name\n     GROUP BY names.queue_name\n       )\n       SELECT usage.*, policy.max_active,\n              COALESCE(blocked.blocked_ready, 0)::text AS blocked_ready,\n              LEAST(dependencies.blocked_tasks, 10000)::text\n                AS dependency_blocked,\n              LEAST(dependencies.pending_edges, 10000)::text\n                AS dependency_pending_edges,\n              LEAST(dependencies.failed_resolutions, 10000)::text\n               AS dependency_failed_resolutions,\n             dependencies.blocked_tasks > 10000\n               OR dependencies.pending_edges > 10000\n               OR dependencies.failed_resolutions > 10000\n               AS dependency_counts_capped,\n              LEAST(children.waiting_parents, 10000)::text\n             AS child_waiting_parents,\n           LEAST(children.pending_children, 10000)::text\n             AS child_pending_children,\n           LEAST(children.unjoined_results, 10000)::text\n             AS child_unjoined_results,\n           LEAST(children.failed_parents, 10000)::text\n             AS child_failed_parents,\n           LEAST(children.canceled_parents, 10000)::text\n             AS child_canceled_parents,\n           children.waiting_parents > 10000\n             OR children.pending_children > 10000\n             OR children.unjoined_results > 10000\n             OR children.failed_parents > 10000\n             OR children.canceled_parents > 10000\n             AS child_counts_capped\n         FROM usage\n         LEFT JOIN workhorse.concurrency_policy policy ON policy.queue_name = usage.queue_name\n         LEFT JOIN LATERAL (\n           SELECT count(*) FILTER (\n                    WHERE usage.concurrency_active::integer >= policy.max_active\n                       OR (\n                         policy.max_active_per_key IS NOT NULL\n                         AND sample.concurrency_key IS NOT NULL\n                         AND sample.key_active >= policy.max_active_per_key\n                       )\n                  )::integer AS blocked_ready\n             FROM (\n               SELECT ready.concurrency_key,\n                      (SELECT count(*)::integer FROM workhorse.task_runtime active\n                        WHERE active.state = 'active'\n                          AND active.queue_name = usage.queue_name\n                          AND active.concurrency_key = ready.concurrency_key\n                          AND active.expires_at > clock_timestamp()) AS key_active\n                 FROM workhorse.task_runtime ready\n                WHERE ready.state = 'ready' AND ready.queue_name = usage.queue_name\n                ORDER BY ready.sequence, ready.task_id LIMIT 100\n             ) sample\n         ) blocked ON policy.queue_name IS NOT NULL\n         CROSS JOIN LATERAL (\n           SELECT\n             (SELECT count(*) FROM (\n               SELECT 1 FROM workhorse.task_runtime runtime\n                WHERE runtime.queue_name = usage.queue_name AND runtime.state = 'blocked'\n                LIMIT 10001\n             ) sampled_blocked)\n               AS blocked_tasks,\n             (SELECT count(*) FROM (\n               SELECT 1 FROM workhorse.task_dependency edge\n                JOIN workhorse.task_runtime runtime ON runtime.task_id = edge.dependent_task_id\n               WHERE runtime.queue_name = usage.queue_name AND runtime.state = 'blocked'\n                 AND edge.released_at IS NULL\n               LIMIT 10001\n             ) sampled_pending)\n               AS pending_edges,\n             (SELECT count(*) FROM (\n               SELECT 1 FROM workhorse.task_outcome outcome\n                JOIN workhorse.task_query query ON query.task_id = outcome.task_id\n               WHERE query.queue_name = usage.queue_name AND outcome.state = 'failed'\n                 AND outcome.error->>'name' = 'DependencyFailed'\n               LIMIT 10001\n             ) sampled_failed) AS failed_resolutions\n         ) dependencies\n         CROSS JOIN LATERAL (\n\n    SELECT\n      (SELECT count(*) FROM (\n        SELECT 1 FROM workhorse.task_runtime runtime\n         WHERE runtime.queue_name = usage.queue_name AND runtime.state = 'blocked'\n           AND EXISTS (\n             SELECT 1 FROM workhorse.task_child edge WHERE edge.parent_task_id = runtime.task_id\n           )\n         LIMIT 10001\n      ) sampled_waiting) AS waiting_parents,\n      (SELECT count(*) FROM (\n        SELECT 1 FROM workhorse.task_child edge\n        JOIN workhorse.task_query parent ON parent.task_id = edge.parent_task_id\n         WHERE parent.queue_name = usage.queue_name AND edge.joined_at IS NULL\n           AND NOT EXISTS (\n             SELECT 1 FROM workhorse.task_outcome outcome WHERE outcome.task_id = edge.child_task_id\n           )\n         LIMIT 10001\n      ) sampled_pending) AS pending_children,\n      (SELECT count(*) FROM (\n        SELECT 1 FROM workhorse.task_child edge\n        JOIN workhorse.task_query parent ON parent.task_id = edge.parent_task_id\n         JOIN workhorse.task_outcome outcome ON outcome.task_id = edge.child_task_id\n        WHERE parent.queue_name = usage.queue_name AND edge.joined_at IS NULL AND outcome.state = 'succeeded'\n         LIMIT 10001\n      ) sampled_unjoined) AS unjoined_results,\n      (SELECT count(*) FROM (\n        SELECT 1 FROM workhorse.task_outcome outcome\n        JOIN workhorse.task_query parent ON parent.task_id = outcome.task_id\n         WHERE parent.queue_name = usage.queue_name AND outcome.state = 'failed'\n           AND outcome.error->>'name' = 'DependencyFailed'\n           AND EXISTS (\n             SELECT 1 FROM workhorse.task_child edge WHERE edge.parent_task_id = outcome.task_id\n           )\n         LIMIT 10001\n      ) sampled_failed) AS failed_parents,\n      (SELECT count(*) FROM (\n        SELECT 1 FROM workhorse.task_outcome outcome\n        JOIN workhorse.task_query parent ON parent.task_id = outcome.task_id\n         WHERE parent.queue_name = usage.queue_name AND outcome.state = 'canceled'\n           AND outcome.error->>'name' = 'DependencyCanceled'\n           AND EXISTS (\n             SELECT 1 FROM workhorse.task_child edge WHERE edge.parent_task_id = outcome.task_id\n           )\n         LIMIT 10001\n      ) sampled_canceled) AS canceled_parents\n         ) children\n        ORDER BY usage.queue_name",
        1);

